import type {Express,RequestHandler} from 'express';
import type {SupabaseClient} from '@supabase/supabase-js';
import {isClanSiteOwner} from './clan-owner-view.js';

const uid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const css=`*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:#100c18;color:#f5f1ff;font:15px/1.5 system-ui}main{max-width:1160px;margin:auto;padding:20px}a{color:#c5a4f5}h1,h2,p{margin:0 0 12px}.hero{position:relative;overflow:hidden;border:1px solid #784bad;border-radius:20px;background:radial-gradient(ellipse at 80% 20%,#9e39f88a,transparent 55%),linear-gradient(120deg,#25113f,#160d28);padding:36px 32px;margin:20px 0;display:flex;align-items:center;justify-content:space-between;gap:18px}.hero h1{font-size:clamp(32px,6vw,60px);font-style:italic;line-height:1;letter-spacing:-.05em}.hero p{color:#d4c1ef;font-size:18px}.trophy{font-size:clamp(54px,12vw,120px);filter:drop-shadow(0 0 18px #c269f8)}.grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:16px}.panel,article{background:#20192e;border:1px solid #523c6b;border-radius:16px;padding:22px;min-width:0;margin-bottom:16px}.field{display:grid;grid-template-columns:145px minmax(0,1fr);gap:10px;align-items:start;margin:18px 0}.field label{font-weight:700}.field b{color:#b37af9;margin-right:8px}input,textarea,select,button{font:inherit;color:#fff;background:#211b30;border:1px solid #65547e;border-radius:9px;padding:10px 12px;min-width:0}textarea{width:100%;resize:vertical;min-height:90px}input[type=number],select{width:100%}input[type=range]{width:100%;accent-color:#ac62f5}.quick,.actions{display:flex;flex-wrap:wrap;gap:8px;margin:9px 0}.quick button{flex:1;min-width:48px}.quick button.selected{background:#7936db;border-color:#b77aff}button{cursor:pointer;font-weight:700}button:disabled{opacity:.5;cursor:default}.primary{background:linear-gradient(100deg,#7932e1,#9d40fa);border-color:#bb79ff;color:#fff;width:100%;padding:13px}.preview{background:linear-gradient(135deg,#2a203e,#22182e 70%,#6130a1);padding:16px;border:1px solid #60477c;border-radius:12px}.preview p{overflow-wrap:anywhere;padding:10px 0;border-bottom:1px solid #ffffff20}.muted,small{color:#b9a8cc}#feedback{min-height:24px;color:#e8ccff;margin-top:12px}#history{display:grid;gap:10px}#history article{margin:0;padding:16px}.row{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.pill{padding:4px 10px;border-radius:20px;background:#4b346c;font-size:12px}.pill[data-state=completed]{background:#205938}.pill[data-state=failed]{background:#6b303b}.pill[data-state=accepted]{background:#664b24}.description{white-space:pre-wrap;overflow-wrap:anywhere}.actions button{flex:1}.accept{background:#5631a1}.reject{background:#632d43}.invite{display:flex;gap:8px;flex-wrap:wrap}.invite input{flex:1}.notice{border:1px solid #8b6c38;background:#332638;padding:10px 14px;border-radius:10px;margin:12px 0;color:#ffe1a5}@media(max-width:680px){main{padding:12px}.grid,.field{grid-template-columns:1fr}.hero{padding:22px 16px}.hero p{font-size:14px}.panel{padding:16px}}body[data-admin=false]{background:#10101b}body[data-admin=false] main{max-width:1240px;padding:9px 18px 24px}body[data-admin=false] main>a{display:inline-block;margin:0 0 8px}body[data-admin=false] .hero{background:#21113c url(data:image/webp;base64,) center/100% 100% no-repeat;aspect-ratio:1200/168;min-height:0;padding:0;margin:0 0 16px;border:0;border-radius:13px}body[data-admin=false] .hero div,body[data-admin=false] .hero .trophy{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}body[data-admin=false] .grid{max-width:1086px;margin:auto;grid-template-columns:minmax(0,2.4fr) minmax(0,1fr);gap:20px}body[data-admin=false] .panel{background:linear-gradient(145deg,#1e1f2c,#161624);border:1px solid #343247;border-radius:12px;padding:20px}body[data-admin=false] aside.panel{background:radial-gradient(ellipse at 90% 95%,#40207885,transparent 52%),#191927}body[data-admin=false] .field{grid-template-columns:165px minmax(0,1fr)}body[data-admin=false] input,body[data-admin=false] textarea,body[data-admin=false] select{background:#202130;border-color:#5b5972}body[data-admin=false] textarea{min-height:74px}body[data-admin=false] .primary{background:linear-gradient(90deg,#8029ff,#912df7)}body[data-admin=false] .preview{background:linear-gradient(145deg,#222236,#292039 70%,#6526bd);border-color:#433957}body[data-admin=false] .field label b{font-style:italic;font-size:20px}body[data-admin=false] .notice{display:none}@media(max-width:680px){body[data-admin=false] main{padding:10px}body[data-admin=false] .grid,body[data-admin=false] .field{grid-template-columns:1fr}body[data-admin=false] .hero{aspect-ratio:1200/168}body[data-admin=false] .panel{padding:14px}}`;
function page(admin:boolean){return `<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Челленджи · Dropso</title><style>${css}</style><body data-admin="${admin}"><main><a href="${admin?'/admin':'/account'}">← Назад</a><header class="hero"><div><h1>ЧЕЛЛЕНДЖИ</h1><p>${admin?'Управление вызовами стримеру':'Брось вызов любимому стримеру'}</p></div><span class="trophy" aria-hidden="true">🏆</span></header><div class="notice">Челленджи · суммы в монетах Dropso</div>${admin?'<section class="panel"><h2>Доступ к тесту</h2><form id="invite" class="invite"><input id="login" required maxlength="25" placeholder="Twitch-ник игрока"><button>Разрешить тест</button></form><p class="muted">Челленджи доступны игрокам по ссылке /challenges. Получатель — владелец сайта.</p><a href="/challenges">Страница игрока →</a></section>':'<div class="grid" id="formGrid" hidden><section class="panel"><h2>⊕ Создать челлендж</h2><form id="create"><div class="field"><label for="streamer"><b>01</b> Кому</label><select id="streamer" disabled><option id="owner">—</option></select></div><div class="field"><label for="description"><b>02</b> Суть челленджа</label><div><textarea id="description" required maxlength="140" placeholder="Игра только с Deagle, 15 киллов"></textarea><small id="counter">0 / 140</small><p class="muted">Не более двух действий</p></div></div><div class="field"><label for="stake"><b>03</b> Ставка</label><div><input id="stake" type="number" required min="5" max="1000" value="100"><div class="quick" id="quick"></div><input aria-label="Ставка в монетах" type="range" id="range" min="5" max="1000" value="100"><small>Доступно: <span id="balance">—</span> монет</small></div></div><button class="primary" id="send">➤ Отправить челлендж</button></form></section><aside class="panel"><h2>Ваш челлендж</h2><div class="preview"><p id="ownerPreview">—</p><p>🪙 Ставка: <b id="stakePreview">100 монет</b></p><p>Суть челленджа:<br><span id="descriptionPreview">—</span></p></div><p class="muted">При принятии ставка резервируется. Если стример провалит челлендж, ты получишь ставку обратно и столько же монет выигрыша.</p></aside></div>'}<p id="feedback" role="status"></p><h2>${admin?'Заявки':'Мои челленджи'}</h2><div id="history"></div></main><script src="/challenges.js" defer></script></body></html>`;}
const js=String.raw`(()=>{'use strict';const $=id=>document.getElementById(id),admin=document.body.dataset.admin==='true',base=admin?'/api/admin/challenges':'/api/challenges';let busy=false,requestId=null,balance=0;const labels={pending:'На рассмотрении',accepted:'Принят',declined:'Отказано',completed:'Выполнен',failed:'Не выполнен'};function n(tag,text){const node=document.createElement(tag);node.textContent=text;return node}
async function api(action,body){const r=await fetch(base+'/'+action,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Сервис временно недоступен');return data}
function render(rows){$('history').replaceChildren();if(!rows.length){$('history').append(n('p','Пока нет челленджей'));return}for(const item of rows){const card=n('article',''),top=n('div',''),status=n('span',labels[item.status]||item.status);top.className='row';status.className='pill';status.dataset.state=item.status;top.append(n('strong',(admin?item.twitch_login+' · ':'')+item.stake+' монет'),status);const description=n('p',item.description);description.className='description';card.append(top,description,n('small',new Date(item.created_at).toLocaleString('ru-RU')));if(admin){const actions=n('div','');actions.className='actions';const opts=item.status==='pending'?[['accept','Принять'],['decline','Отказаться']]:item.status==='accepted'?[['complete','Выполнен'],['fail','Не выполнен']]:[];for(const [action,label] of opts){const b=n('button',label);b.className=action==='accept'||action==='complete'?'accept':'reject';b.onclick=()=>{if((action==='complete'||action==='fail')&&!confirm(label+'? Итог будет окончательным.'))return;act(action,{id:item.id})};actions.append(b)}card.append(actions)}$('history').append(card)}}
async function load(){const d=await api('state');render(d.rows);if(!admin){balance=d.balance;$('balance').textContent=balance.toLocaleString('ru-RU');$('owner').textContent=d.owner;$('ownerPreview').textContent='👤 '+d.owner;$('formGrid').hidden=false;sync()}}
async function act(action,body){if(busy)return;busy=true;try{await api(action,body);$('feedback').textContent='Готово';if(action==='create'){$('description').value='';requestId=null}await load()}catch(e){$('feedback').textContent=e.message}finally{busy=false;if(!admin)sync()}}
function sync(){const amount=Number($('stake').value),text=$('description').value;$('stakePreview').textContent=amount+' монет';$('descriptionPreview').textContent=text||'—';$('counter').textContent=text.length+' / 140';$('range').value=amount;for(const b of $('quick').children)b.classList.toggle('selected',Number(b.textContent)===amount);$('send').disabled=busy||!text.trim()||!Number.isInteger(amount)||amount<5||amount>1000||amount>balance}
if(admin){$('invite').onsubmit=e=>{e.preventDefault();act('invite',{login:$('login').value.trim()})}}else{for(const amount of [5,50,100,250,500,1000]){const b=n('button',amount);b.type='button';b.onclick=()=>{$('stake').value=amount;requestId=null;sync()};$('quick').append(b)}$('range').oninput=()=>{$('stake').value=$('range').value;requestId=null;sync()};for(const id of ['stake','description'])$(id).oninput=()=>{requestId=null;sync()};$('create').onsubmit=e=>{e.preventDefault();if(!requestId)requestId=crypto.randomUUID();act('create',{id:requestId,description:$('description').value.trim(),stake:Number($('stake').value)})}}
const refresh=()=>load().catch(e=>{$('feedback').textContent=e.message});refresh();setInterval(()=>{if(!busy&&!document.hidden)refresh()},10000)})();`;
export function installChallenges(app:Express,db:SupabaseClient,user:RequestHandler,admin:RequestHandler,origin:string){
 const owner:RequestHandler=async(_q,r,n)=>{try{if(!await isClanSiteOwner(db,r.locals.session.twitchUserId))return void r.sendStatus(403);n()}catch{r.sendStatus(503)}};
 const noStore:RequestHandler=(_q,r,n)=>{r.set('Cache-Control','private, no-store');n()};
 const guard:RequestHandler=(q,r,n)=>{if(q.get('sec-fetch-site')==='cross-site'||(q.get('origin')&&q.get('origin')!==origin)||!q.is('application/json'))return void r.sendStatus(403);n()};
 const errors:Record<string,string>={pilot_closed:'Закрытый тест. Доступ по приглашению владельца.',insufficient_coins:'Недостаточно монет',invalid_status:'Челлендж уже обработан',user_not_found:'Игрок не найден',user_required:'Аккаунт недоступен',owner_required:'Только владелец',invalid_request:'Проверь описание и ставку',request_conflict:'Создай новый запрос',challenge_not_found:'Челлендж не найден'};
 async function rpc(r:any,action:string,body:any={}){const {data,error}=await db.rpc('rewards_challenges_rpc',{p_actor:r.locals.session.twitchUserId,p_action:action,p_body:body});if(error)return r.status(['pilot_closed','owner_required','user_required'].includes(error.message)?403:errors[error.message]?409:503).json({error:errors[error.message]||'Сервис временно недоступен'});return r.json(data)}
 app.get('/challenges',noStore,user,(_q,r)=>r.send(page(false)));
 app.get('/admin/challenges',noStore,admin,owner,(_q,r)=>r.send(page(true)));
 app.get('/challenges.js',noStore,(_q,r)=>r.type('application/javascript').send(js));
 app.get('/api/challenges/state',noStore,user,(_q,r)=>rpc(r,'state'));
 app.post('/api/challenges/create',noStore,user,guard,(q,r)=>{const b=q.body;if(!b||!uid.test(b.id)||typeof b.description!=='string'||b.description.trim().length<1||b.description.trim().length>140||!Number.isInteger(b.stake)||b.stake<5||b.stake>1000)return void r.sendStatus(400);return rpc(r,'create',{id:b.id,description:b.description.trim(),stake:b.stake})});
 app.get('/api/admin/challenges/state',noStore,admin,owner,(_q,r)=>rpc(r,'admin_state'));
 app.post('/api/admin/challenges/:action',noStore,admin,owner,guard,(q,r)=>{const action=String(q.params.action),b=q.body;if(action==='invite'){if(typeof b?.login!=='string'||!/^[A-Za-z0-9_]{1,25}$/.test(b.login))return void r.sendStatus(400);return rpc(r,action,{login:b.login})}if(!['accept','decline','complete','fail'].includes(action)||!uid.test(b?.id))return void r.sendStatus(400);return rpc(r,action,{id:b.id})});
}
